import sqlite3
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key) VALUES ('admin', 'admin@corp.internal', 'superadmin', 'sk-prod-9f8a7b6c5d4e3f2a1b')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key) VALUES ('svc-billing', 'billing@corp.internal', 'service', 'sk-prod-billing-x7y8z9')")
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    if not value:
        return jsonify({'error': 'Query parameter q is required'}), 400

    # Build query with validated field name and user-supplied value
    query = f"SELECT username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]

        # Log the search for compliance
        db.execute("INSERT INTO audit_log (action, details) VALUES (?, ?)",
                   ('user_search', f'field={field}, q={value}'))
        db.commit()

        return jsonify({'results': users, 'count': len(users)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>/profile', methods=['GET'])
def get_profile(user_id):
    """Get user profile by ID. Internal use only."""
    db = get_db()
    user = db.execute('SELECT username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

@app.route('/internal/metrics', methods=['GET'])
def metrics():
    db = get_db()
    user_count = db.execute('SELECT COUNT(*) FROM users').fetchone()[0]
    log_count = db.execute('SELECT COUNT(*) FROM audit_log').fetchone()[0]
    return jsonify({'users': user_count, 'audit_entries': log_count})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=os.environ.get('FLASK_DEBUG', '0') == '1')
